def reserve(campaign, attempt, task, **context):
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]*", attempt):
        raise ValueError("Attempt identifier must contain lowercase letters, numbers, - or _")
    campaign = Path(campaign)
    with locked(campaign):
        path = campaign / "ledger.json"
        ledger = read_json(path) if path.exists() else {"schema_version": 1, "checkpoint": CHECKPOINT, "calls": []}
        if ledger["checkpoint"] != CHECKPOINT:
            raise ValueError("Campaign checkpoint changed; explicit review required")
        if any(c["attempt"] == attempt for c in ledger["calls"]):
            raise ValueError("Attempt already reserved; inspect it or use a new attempt identifier")
        if len(ledger["calls"]) >= CHECKPOINT:
            raise ValueError("200 calls reserved: check back with the user before call 201")
        entry = {"call": len(ledger["calls"]) + 1, "attempt": attempt,
                 "task": task["id"], "task_sha256": sha(json.dumps(task, sort_keys=True).encode()),
                 "base_commit": task["base_commit"], "reserved_at": now(), "state": "reserved", **context}
        ledger["calls"].append(entry)
        atomic_json(path, ledger)
        return entry

def verify(path):
    manifest = json.loads(path.read_text())
    archive = path.parent / manifest["archive"]
    sha = lambda data: hashlib.sha256(data).hexdigest()
    if sha(archive.read_bytes()) != manifest["archive_sha256"]:
        raise ValueError("Worker evidence archive hash mismatch")
    with tarfile.open(archive, "r:gz") as stream:
        members = stream.getmembers()
        if len(members) != len(manifest["members"]) or {m.name for m in members} != set(manifest["members"]):
            raise ValueError("Missing, duplicate or unexpected evidence member")
        for member in members:
            if not member.isfile():
                raise ValueError("Only regular evidence files are allowed")
            data = stream.extractfile(member).read()
            expected = manifest["members"][member.name]
            if len(data) != expected["bytes"] or sha(data) != expected["sha256"]:
                raise ValueError("Evidence member mismatch: " + member.name)
    return len(members)


def default_manifests(root=ROOT):
    """Each archived trial owns one independently verified manifest."""
    manifests = sorted((root / "formalization/results").glob("*/evidence-manifest.json"))
    if not manifests:
        raise ValueError("No archived worker evidence manifests found")
    return manifests


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("manifest", nargs="*", type=Path,
                        help="Explicit manifests; default: every archived trial")
    args = parser.parse_args()
    manifests = args.manifest or default_manifests()
    total = sum(verify(path) for path in manifests)
    print(f"Worker evidence: {total} archived files across {len(manifests)} trials verified.")
